local M = "SUPER"
local home = os.getenv("HOME") or ""
local bin = home .. "/.config/navuryx/bin/"
local terminal = bin .. "navuryx-terminal"
local browser = "xdg-open https://duckduckgo.com"
local editor = "bash -lc 'command -v code >/dev/null && exec code || command -v codium >/dev/null && exec codium || command -v nvim >/dev/null && exec kitty -e nvim || exec kitty'"
local files = "bash -lc 'command -v dolphin >/dev/null && exec dolphin || command -v thunar >/dev/null && exec thunar || command -v nautilus >/dev/null && exec nautilus || exec kitty -e lf'"

hl.bind(M .. " + Return", hl.dsp.exec_cmd(terminal))
hl.bind(M .. " + T", hl.dsp.exec_cmd(terminal))
hl.bind("CTRL + ALT + T", hl.dsp.exec_cmd(terminal))
hl.bind(M .. " + E", hl.dsp.exec_cmd(files))
hl.bind(M .. " + B", hl.dsp.exec_cmd(browser))
hl.bind(M .. " + C", hl.dsp.exec_cmd(editor))
hl.bind(M .. " + SPACE", hl.dsp.exec_cmd(bin .. "navuryx-spotlight"))
hl.bind(M .. " + CTRL + Return", hl.dsp.exec_cmd(bin .. "navuryx-spotlight"))
hl.bind(M .. " + SHIFT + SPACE", hl.dsp.exec_cmd(bin .. "navuryx-command"))
hl.bind(M .. " + A", hl.dsp.exec_cmd(bin .. "navuryx-ai"))
hl.bind(M .. " + ALT + A", hl.dsp.exec_cmd(bin .. "navuryx-ask-screen"))
hl.bind(M .. " + Q", hl.dsp.window.close())
hl.bind(M .. " + SHIFT + ALT + Q", hl.dsp.exec_cmd("hyprctl kill"))
hl.bind(M .. " + ALT + SPACE", hl.dsp.window.float({ action = "toggle" }))
hl.bind(M .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind(M .. " + D", hl.dsp.window.fullscreen({ mode = "maximized", action = "toggle" }))
hl.bind(M .. " + P", hl.dsp.window.pin())
hl.bind(M .. " + L", hl.dsp.exec_cmd("loginctl lock-session || hyprlock"))
hl.bind(M .. " + SHIFT + L", hl.dsp.exec_cmd("systemctl suspend || loginctl suspend"), { locked = true })
hl.bind(M .. " + V", hl.dsp.exec_cmd(bin .. "navuryx-clipboard"))
hl.bind(M .. " + W", hl.dsp.exec_cmd(bin .. "navuryx-wallpaper"))
hl.bind(M .. " + CTRL + W", hl.dsp.exec_cmd(bin .. "navuryx-wallpaper"))
hl.bind(M .. " + SHIFT + W", hl.dsp.exec_cmd(bin .. "navuryx-wallpaper --random"))
hl.bind(M .. " + CTRL + T", hl.dsp.exec_cmd(bin .. "navuryx-wallpaper --random"))
hl.bind(M .. " + comma", hl.dsp.exec_cmd(bin .. "navuryx-settings"))
hl.bind(M .. " + SHIFT + S", hl.dsp.exec_cmd(bin .. "navuryx-screenshot"))
hl.bind(M .. " + ALT + S", hl.dsp.exec_cmd(bin .. "navuryx-screenshot --menu"))
hl.bind(M .. " + SHIFT + X", hl.dsp.exec_cmd(bin .. "navuryx-screenshot ocr"))
hl.bind(M .. " + ALT + R", hl.dsp.exec_cmd(bin .. "navuryx-record"), { locked = true })
hl.bind(M .. " + SHIFT + R", hl.dsp.exec_cmd(bin .. "navuryx-record"), { locked = true })
hl.bind(M .. " + SHIFT + E", hl.dsp.exec_cmd(bin .. "navuryx-power"))
hl.bind(M .. " + CTRL + P", hl.dsp.exec_cmd(bin .. "navuryx-power --rofi"))
hl.bind("CTRL + ALT + Delete", hl.dsp.exec_cmd(bin .. "navuryx-power"))
hl.bind(M .. " + N", hl.dsp.exec_cmd(bin .. "navuryx-control"))
hl.bind(M .. " + I", hl.dsp.exec_cmd(bin .. "navuryx-settings"))
hl.bind(M .. " + slash", hl.dsp.exec_cmd(bin .. "navuryx-settings"))
hl.bind(M .. " + TAB", hl.dsp.exec_cmd(bin .. "navuryx-overview"))
hl.bind(M .. " + SHIFT + N", hl.dsp.exec_cmd(bin .. "navuryx-notifications"))
hl.bind(M .. " + SHIFT + T", hl.dsp.exec_cmd(bin .. "navuryx-theme"))
hl.bind(M .. " + K", hl.dsp.exec_cmd(bin .. "navuryx-keybinds"))
hl.bind(M .. " + SHIFT + V", hl.dsp.exec_cmd(bin .. "navuryx-vpn"))
hl.bind(M .. " + SHIFT + G", hl.dsp.exec_cmd(bin .. "navuryx-gaming"))
hl.bind(M .. " + ALT + period", hl.dsp.exec_cmd(bin .. "navuryx-wallpaper --next"))
hl.bind(M .. " + ALT + comma", hl.dsp.exec_cmd(bin .. "navuryx-wallpaper --random"))
hl.bind(M .. " + SHIFT + C", hl.dsp.exec_cmd("hyprpicker -a"))
hl.bind("Print", hl.dsp.exec_cmd(bin .. "navuryx-screenshot"), { locked = true })
hl.bind("CTRL + SUPER + SHIFT + D", hl.dsp.exec_cmd(bin .. "navuryx-appearance --toggle"))
hl.bind(M .. " + SHIFT + ALT + slash", hl.dsp.exec_cmd(bin .. "navuryx-welcome --force"))

hl.bind(M .. " + left", hl.dsp.focus({ direction = "left" }))
hl.bind(M .. " + right", hl.dsp.focus({ direction = "right" }))
hl.bind(M .. " + up", hl.dsp.focus({ direction = "up" }))
hl.bind(M .. " + down", hl.dsp.focus({ direction = "down" }))
hl.bind(M .. " + SHIFT + left", hl.dsp.window.move({ direction = "l" }))
hl.bind(M .. " + SHIFT + right", hl.dsp.window.move({ direction = "r" }))
hl.bind(M .. " + SHIFT + up", hl.dsp.window.move({ direction = "u" }))
hl.bind(M .. " + SHIFT + down", hl.dsp.window.move({ direction = "d" }))
hl.bind(M .. " + ALT + left", hl.dsp.window.swap({ direction = "l" }))
hl.bind(M .. " + ALT + right", hl.dsp.window.swap({ direction = "r" }))
hl.bind(M .. " + ALT + up", hl.dsp.window.swap({ direction = "u" }))
hl.bind(M .. " + ALT + down", hl.dsp.window.swap({ direction = "d" }))
hl.bind(M .. " + J", hl.dsp.layout("togglesplit"))
hl.bind(M .. " + Semicolon", hl.dsp.layout("splitratio -0.1"), { repeating = true })
hl.bind(M .. " + Apostrophe", hl.dsp.layout("splitratio +0.1"), { repeating = true })

for i = 1, 10 do
    local key = i % 10
    hl.bind(M .. " + " .. key, hl.dsp.focus({ workspace = i }))
    hl.bind(M .. " + SHIFT + " .. key, hl.dsp.window.move({ workspace = i }))
    hl.bind(M .. " + ALT + " .. key, hl.dsp.window.move({ workspace = i, follow = false }))
end

hl.bind(M .. " + S", hl.dsp.workspace.toggle_special("scratch"))
hl.bind(M .. " + ALT + S", hl.dsp.window.move({ workspace = "special:scratch", follow = false }))
hl.bind(M .. " + grave", hl.dsp.workspace.toggle_special("scratch"))
hl.bind(M .. " + SHIFT + grave", hl.dsp.window.move({ workspace = "special:scratch" }))
hl.bind("CTRL + SUPER + Left", hl.dsp.focus({ workspace = "r-1" }))
hl.bind("CTRL + SUPER + Right", hl.dsp.focus({ workspace = "r+1" }))
hl.bind(M .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(M .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))
hl.bind(M .. " + mouse:272", hl.dsp.window.drag(), { mouse = true })
hl.bind(M .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd(bin .. "navuryx-osd volume-up"), { locked = true, repeating = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd(bin .. "navuryx-osd volume-down"), { locked = true, repeating = true })
hl.bind("XF86AudioMute", hl.dsp.exec_cmd(bin .. "navuryx-osd mute"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd(bin .. "navuryx-osd mic-mute"), { locked = true })
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd(bin .. "navuryx-osd brightness-up"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd(bin .. "navuryx-osd brightness-down"), { locked = true, repeating = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })
